<?php
 namespace App; use App\Library\Helper; use App\Model_ as Model; class PayWay extends Model { protected $guarded = []; protected $casts = [ 'channels' => 'array', ]; const ENABLED_DISABLED = 0; const ENABLED_PC = 1; const ENABLED_MOBILE = 2; const ENABLED_ALL = 3; const TYPE_SHOP = 1; const TYPE_API = 2; public function getPayByWeight() { $count = $base = 0; $map = []; $ids = []; foreach ($this->channels as $item) { $ids[] = intval($item[0]); } $pays = \App\Pay::gets()->filter(function ($pay) use ($ids) { return in_array($pay->id, $ids); }); $pays_map = []; foreach ($pays as $pay_model) { $pays_map[$pay_model->id] = $pay_model; } foreach ($this->channels as $item) { $pay_id = intval($item[0]); $weight = intval($item[1]); if ($weight && isset($pays_map[$pay_id]) && $pays_map[$pay_id]->enabled > 0) { $count += $weight; $max = $base + $weight; $map[] = [ 'min' => $base, 'max' => $max, 'pay_id' => $pay_id, ]; $base = $max; } } if ($count <= 0) { return null; } $rand = mt_rand(0, $count - 1); foreach ($map as $current) { if ($current['min'] <= $rand && $rand < $current['max']) { return $pays_map[$current['pay_id']]; } } return null; } public static function gets($user, $closure = null) { $query = self::query(); if ($closure !== null) $query->where($closure); $all = $query->orderBy('sort')->get(['name', 'img', 'channels']); $result_pays = []; foreach ($all as $pay_way) { $pay = $pay_way->getPayByWeight(); if ($pay) { $pay->setAttribute('name', $pay_way->name); $pay->setAttribute('img', $pay_way->img); $pay->setVisible(['id', 'name', 'img', 'fee']); $result_pays[] = $pay; } } return $result_pays; } } 